package com.c016.pushupflappy.game.flappy

import android.content.res.Resources
import android.graphics.Canvas
import android.graphics.Color
import com.c016.pushupflappy.R

/**
 * Original pixel art in the style of the classic Flappy Bird: a round yellow bird flying between
 * green pipes. The art is generated by tools/classic_art.py and drawn without filtering so the
 * pixels stay crisp.
 */
class ClassicSkin(resources: Resources) : FlappySkin(pixelated = true) {

    override val background = resources.bitmap(R.drawable.classic_background)
    override val backgroundBottom = FlappyWorld.GROUND_Y
    override val ground = resources.bitmap(R.drawable.classic_ground)
    override val groundTop = FlappyWorld.GROUND_Y
    override val playerFrames = listOf(
        resources.bitmap(R.drawable.classic_bird_1),
        resources.bitmap(R.drawable.classic_bird_2),
        resources.bitmap(R.drawable.classic_bird_3),
    )

    // Wing goes up, middle, down, middle.
    override val playerAnimation = intArrayOf(0, 1, 2, 1)
    override val playerWidth = 0.13f
    override val digits = listOf(
        R.drawable.classic_digit_0, R.drawable.classic_digit_1, R.drawable.classic_digit_2,
        R.drawable.classic_digit_3, R.drawable.classic_digit_4, R.drawable.classic_digit_5,
        R.drawable.classic_digit_6, R.drawable.classic_digit_7, R.drawable.classic_digit_8,
        R.drawable.classic_digit_9,
    ).map { resources.bitmap(it) }
    override val titles = mapOf(
        FlappyTitle.GET_READY to resources.bitmap(R.drawable.classic_text_get_ready),
        FlappyTitle.GAME_OVER to resources.bitmap(R.drawable.classic_text_game_over),
    )
    override val panel = resources.bitmap(R.drawable.classic_panel)
    override val medals = mapOf(
        FlappyMedal.BRONZE to resources.bitmap(R.drawable.classic_medal_bronze),
        FlappyMedal.SILVER to resources.bitmap(R.drawable.classic_medal_silver),
        FlappyMedal.GOLD to resources.bitmap(R.drawable.classic_medal_gold),
    )
    override val panelTextColor = Color.rgb(84, 56, 71)
    override val obstacleReach = CAP_HALF_WIDTH

    /** One pixel row, stretched to any length. */
    private val pipeBody = resources.bitmap(R.drawable.classic_pipe_body)
    private val pipeCap = resources.bitmap(R.drawable.classic_pipe_cap)

    override fun drawObstacle(canvas: Canvas, x: Float, gapTop: Float, gapBottom: Float, u: Float) {
        val bodyLeft = (x - BODY_HALF_WIDTH) * u
        val bodyRight = (x + BODY_HALF_WIDTH) * u
        val capLeft = (x - CAP_HALF_WIDTH) * u
        val capRight = (x + CAP_HALF_WIDTH) * u

        drawBitmap(canvas, pipeBody, bodyLeft, 0f, bodyRight, gapTop * u)
        // The upper cap is the lower one flipped upside down.
        canvas.save()
        canvas.scale(1f, -1f, 0f, (gapTop - CAP_HEIGHT / 2f) * u)
        drawBitmap(canvas, pipeCap, capLeft, (gapTop - CAP_HEIGHT) * u, capRight, gapTop * u)
        canvas.restore()

        drawBitmap(canvas, pipeBody, bodyLeft, gapBottom * u, bodyRight, FlappyWorld.GROUND_Y * u)
        drawBitmap(canvas, pipeCap, capLeft, gapBottom * u, capRight, (gapBottom + CAP_HEIGHT) * u)
    }

    override fun hitsObstacle(x: Float, gapTop: Float, gapBottom: Float, px: Float, py: Float, r: Float): Boolean =
        circleHitsRect(px, py, r, x - BODY_HALF_WIDTH, -1f, x + BODY_HALF_WIDTH, gapTop) ||
            circleHitsRect(px, py, r, x - CAP_HALF_WIDTH, gapTop - CAP_HEIGHT, x + CAP_HALF_WIDTH, gapTop) ||
            circleHitsRect(px, py, r, x - BODY_HALF_WIDTH, gapBottom, x + BODY_HALF_WIDTH, 2f) ||
            circleHitsRect(px, py, r, x - CAP_HALF_WIDTH, gapBottom, x + CAP_HALF_WIDTH, gapBottom + CAP_HEIGHT)

    private fun circleHitsRect(px: Float, py: Float, r: Float, left: Float, top: Float, right: Float, bottom: Float): Boolean {
        val dx = px - px.coerceIn(left, right)
        val dy = py - py.coerceIn(top, bottom)
        return dx * dx + dy * dy < r * r
    }

    private companion object {
        /** The pipe art is 26 px wide (body) and 30 x 14 px (cap). */
        const val PIXEL = 0.15f / 26f
        const val BODY_HALF_WIDTH = 13 * PIXEL
        const val CAP_HALF_WIDTH = 15 * PIXEL
        const val CAP_HEIGHT = 14 * PIXEL
    }
}
